fun eval(v) = v match {
  case n is Number -> n
  case o is Object -> o.op match {
    case "+" -> o.l + o.r
    case "-" -> o.l - o.r
    case "*" -> o.l * o.r
    case "/" -> o.l / o.r
  }
}
